            return 0.0f;
        break;
    case SPELL_DESTROY_UNDEAD:
        if (!(attrs & CTA_UNDEAD))
            return 0.0f;
        if (target_hero
            && const_cast<hero*>(target_hero)->IsWieldingArtifact(ARTIFACT_PENDANT_OF_DEATH))
            return 0.0f;
        break;
    case SPELL_RESURRECTION:
        if (attrs & CTA_UNDEAD)
            return 0.0f;
        if (akCreatureTypeTraits[target_army_type].damageHighBound == 0)
            return 0.0f;
        break;
    case SPELL_ANIMATE_DEAD:
        if (!(attrs & CTA_UNDEAD))
            return 0.0f;
        if (akCreatureTypeTraits[target_army_type].damageHighBound == 0)
            return 0.0f;
        break;
    case SPELL_BLESS:
    case SPELL_FORTUNE:
    case SPELL_MISFORTUNE:
    case SPELL_SLAYER:
        if (attrs & CTA_UNDEAD)
            return 0.0f;
        if (akCreatureTypeTraits[target_army_type].damageHighBound == 0)
            return 0.0f;
        break;
